def compute(vars):
    values = {
        "2019": vars["v1"],
        "2018": vars["v2"],
        "2017": vars["v3"],
    }
    lowest_year = min(values, key=values.get)
    return {
        "value": lowest_year,
        "trace": {
            "interest_income_by_year": values,
            "lowest_interest_income": values[lowest_year],
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
